core_reasoning_1:
\textbf{Claim.}
For the scalar mode dual to the dimension-2 operator in the soliton background with boundary dimension \(d=4\),
\[
m^2R^2=-4=-\frac{d^2}{4}.
\]
Moreover, the soliton has vanishing logarithmic source coefficient \(J_\Phi=0\), and its one-point function is
\[
\langle O\rangle=2\Phi_0=\frac{2\sqrt{2}L^2}{\sqrt{3}}\eta .
\]

\textbf{Premises.}
\[
\begin{aligned}
\text{(P1)}\quad &d=4,\qquad \Delta=2,\qquad R>0.\\
\text{(P2)}\quad &m^2R^2=\Delta(\Delta-d).\\
\text{(P3)}\quad &\text{The Breitenlohner--Freedman bound in dimension }d\text{ is }m^2R^2\ge -\frac{d^2}{4}.\\
\text{(P4)}\quad &\Phi_1=\frac{J_\Phi\ln(\rho^2/\rho_0^2)}{\rho^2}+\frac{\Phi_0}{\rho^2}+O\!\left(\frac{\ln(\rho^2/\rho_0^2)}{\rho^4}\right).\\
\text{(P5)}\quad &\Phi_1=\frac{\Phi_0}{\rho^2}+\frac{\sqrt{6}\Phi_0^2}{12\rho^4}+O(\rho^{-8}),\qquad
\Phi_0=\frac{\sqrt{2}L^2}{\sqrt{3}}\eta.\\
\text{(P6)}\quad &\text{For }\Delta=d/2=2,\text{ the coefficient }J_\Phi\text{ is the source and }\langle O\rangle=2\Phi_0.\\
\text{(P7)}\quad &\text{Asymptotic coefficients multiplying linearly independent functions of }\rho\text{ are unique.}
\end{aligned}
\]

\textbf{Derivation.}
\begin{align}
m^2R^2
&=\Delta(\Delta-d) &&\text{by (P2)}\\
&=2(2-4) &&\text{by (P1)}\\
&=-4. &&\text{arithmetic}
\end{align}
\begin{align}
-\frac{d^2}{4}
&=-\frac{4^2}{4} &&\text{by (P1)}\\
&=-4, &&\text{arithmetic}
\end{align}
so \(m^2R^2=-d^2/4\), saturating (P3).
The coefficient of \(\rho^{-2}\ln(\rho^2/\rho_0^2)\) in the general BF-bound expansion is
\begin{align}
\operatorname{coeff}_{\rho^{-2}\ln(\rho^2/\rho_0^2)}(\Phi_1)
&=J_\Phi &&\text{by (P4)}.
\end{align}
For the soliton expansion,
\begin{align}
\operatorname{coeff}_{\rho^{-2}\ln(\rho^2/\rho_0^2)}(\Phi_1)
&=0 &&\text{by (P5), since no such term occurs}\\
J_\Phi&=0 &&\text{by uniqueness (P7)}.
\end{align}
Finally,
\begin{align}
\langle O\rangle
&=2\Phi_0 &&\text{by (P6)}\\
&=2\left(\frac{\sqrt{2}L^2}{\sqrt{3}}\eta\right) &&\text{by (P5)}\\
&=\frac{2\sqrt{2}L^2}{\sqrt{3}}\eta. &&\text{algebra}
\end{align}

\textbf{Final Result.}
\[
\boxed{m^2R^2=-4=-\frac{d^2}{4},\qquad J_\Phi=0,
\qquad \langle O\rangle=2\Phi_0=\frac{2\sqrt{2}L^2}{\sqrt{3}}\eta}
\]
\hfill$\blacksquare$

core_reasoning_2:
\textbf{Claim.}
On the five-dimensional supersymmetric branch \(q_1=-q_2\), the normalized Wilson-line sources determine the soliton centre by
\[
x_0=\frac{\psi_2}{\psi_1},
\]
provided \(q_1\delta(x_0-1)\psi_1\neq0\).

\textbf{Premises.}
\[
\begin{aligned}
\text{(P1)}\quad &q_1=-q_2.\\
\text{(P2)}\quad &q_1(1-x_0^{-1})L\delta=2\pi L\psi_1.\\
\text{(P3)}\quad &q_2(1-x_0)L\delta=2\pi L\psi_2.\\
\text{(P4)}\quad &L>0,
\qquad \delta>0,
\qquad q_1\neq0,
\qquad x_0\neq1,
\qquad \psi_1\neq0.
\end{aligned}
\]

\textbf{Derivation.}
From the first Wilson-line definition,
\begin{align}
q_1(1-x_0^{-1})L\delta
&=2\pi L\psi_1 &&\text{by (P2)}\\
q_1\frac{x_0-1}{x_0}\delta
&=2\pi\psi_1 &&\text{divide by }L>0\text{ and simplify}. \label{eq:qone}
\end{align}
From the second Wilson-line definition,
\begin{align}
q_2(1-x_0)L\delta
&=2\pi L\psi_2 &&\text{by (P3)}\\
q_2(1-x_0)\delta
&=2\pi\psi_2 &&\text{divide by }L>0\\
(-q_1)(1-x_0)\delta
&=2\pi\psi_2 &&\text{by (P1)}\\
q_1(x_0-1)\delta
&=2\pi\psi_2. \label{eq:qtwo}

tag{1}
\end{align}
Multiplying \eqref{eq:qone} by \(x_0\) gives
\begin{align}
q_1(x_0-1)\delta
&=2\pi x_0\psi_1. \label{eq:qone-scaled}
\end{align}
Equating \eqref{eq:qtwo} and \eqref{eq:qone-scaled},
\begin{align}
2\pi x_0\psi_1
&=2\pi\psi_2 &&\text{same left-hand side}\\
x_0\psi_1&=\psi_2 &&\text{divide by }2\pi\\
x_0&=\frac{\psi_2}{\psi_1} &&\text{divide by }\psi_1\neq0.
\end{align}

\textbf{Final Result.}
\[
\boxed{x_0=\frac{\psi_2}{\psi_1}}
\]
\hfill$\blacksquare$

core_reasoning_4:
\textbf{Claim.}
For a regular branch with \(x_0>0\) and \(x_0\neq1\), the normalized holographic energy is
\[
F_\Phi=-16\frac{(\psi_1^2x_0^2-\psi_2^2)(\psi_1^2x_0-\psi_2^2)}{x_0(x_0-1)^2}.
\]
Consequently, \(F_\Phi=0\) exactly when
\[
\psi_1^2x_0^2=\psi_2^2
\quad\text{or}\quad
\psi_1^2x_0=\psi_2^2.
\]

\textbf{Premises.}
\[
\begin{aligned}
\text{(P1)}\quad &\langle T_{tt}\rangle=-\frac{\mu}{2L^3\kappa},
\qquad E_\Phi:=\langle T_{tt}\rangle V_2\delta.\\
\text{(P2)}\quad &E_0=-\frac{L^3\pi^4}{2\kappa\delta^3}V_2,
\qquad F_\Phi:=\frac{E_\Phi}{|E_0|}.\\
\text{(P3)}\quad &\mu=-\eta L^4(q_1^2-q_2^2).\\
\text{(P4)}\quad &F(x)=L^{-2}+\frac{(x-1)^2(q_1^2-q_2^2x)}{\eta x^2},
\qquad F(x_0)=0.\\
\text{(P5)}\quad &q_1=\frac{2\pi\psi_1x_0}{\delta(x_0-1)},
\qquad q_2=-\frac{2\pi\psi_2}{\delta(x_0-1)}.\\
\text{(P6)}\quad &L>0,
\qquad \kappa>0,
\qquad \delta>0,
\qquad V_2>0,
\qquad x_0>0,
\qquad x_0\neq1.
\end{aligned}
\]

\textbf{Derivation.}
First compute the normalization factor:
\begin{align}
|E_0|&=\frac{L^3\pi^4}{2\kappa\delta^3}V_2 &&\text{by (P2) and (P6)}.
\end{align}
Hence
\begin{align}
F_\Phi
&=\frac{E_\Phi}{|E_0|} &&\text{by (P2)}\\
&=\left(-\frac{\mu}{2L^3\kappa}V_2\delta\right)
\left(\frac{2\kappa\delta^3}{L^3\pi^4V_2}\right) &&\text{by (P1)}\\
&=-\frac{\mu\delta^4}{L^6\pi^4}. \label{eq:F-mu}
\end{align}
From regularity at \(x_0\),
\begin{align}
0&=L^{-2}+\frac{(x_0-1)^2(q_1^2-q_2^2x_0)}{\eta x_0^2} &&\text{by (P4)}\\
\eta
&=-L^2\frac{(x_0-1)^2(q_1^2-q_2^2x_0)}{x_0^2}. \label{eq:eta-reg}
\end{align}
Substitute \eqref{eq:eta-reg} into \(\mu\):
\begin{align}
\mu
&=-\eta L^4(q_1^2-q_2^2) &&\text{by (P3)}\\
&=L^6\frac{(x_0-1)^2(q_1^2-q_2^2x_0)(q_1^2-q_2^2)}{x_0^2}. \label{eq:mu-reg}
\end{align}
Now use the source variables:
\begin{align}
q_1^2-q_2^2x_0
&=\frac{4\pi^2}{\delta^2(x_0-1)^2}\left(\psi_1^2x_0^2-\psi_2^2x_0\right) &&\text{by (P5)}\\
&=\frac{4\pi^2x_0(\psi_1^2x_0-\psi_2^2)}{\delta^2(x_0-1)^2}, \label{eq:factor-one}\\
q_1^2-q_2^2
&=\frac{4\pi^2(\psi_1^2x_0^2-\psi_2^2)}{\delta^2(x_0-1)^2}. \label{eq:factor-two}
\end{align}
Insert \eqref{eq:factor-one}--\eqref{eq:factor-two} into \eqref{eq:mu-reg}:
\begin{align}
\mu
&=L^6\frac{(x_0-1)^2}{x_0^2}
\left(\frac{4\pi^2x_0(\psi_1^2x_0-\psi_2^2)}{\delta^2(x_0-1)^2}\right)
\left(\frac{4\pi^2(\psi_1^2x_0^2-\psi_2^2)}{\delta^2(x_0-1)^2}\right)\\
&=\frac{16L^6\pi^4(\psi_1^2x_0-\psi_2^2)(\psi_1^2x_0^2-\psi_2^2)}{\delta^4x_0(x_0-1)^2}. \label{eq:mu-source}
\end{align}
Therefore
\begin{align}
F_\Phi
&=-\frac{\delta^4}{L^6\pi^4}
\left[\frac{16L^6\pi^4(\psi_1^2x_0-\psi_2^2)(\psi_1^2x_0^2-\psi_2^2)}{\delta^4x_0(x_0-1)^2}\right] &&\text{by \eqref{eq:F-mu}}\\
&=-16\frac{(\psi_1^2x_0^2-\psi_2^2)(\psi_1^2x_0-\psi_2^2)}{x_0(x_0-1)^2}. \label{eq:energy-final}
\end{align}
Since \(x_0(x_0-1)^2\neq0\),
\begin{align}
F_\Phi=0
&\Longleftrightarrow (\psi_1^2x_0^2-\psi_2^2)(\psi_1^2x_0-\psi_2^2)=0 &&\text{by \eqref{eq:energy-final}}\\
&\Longleftrightarrow \psi_1^2x_0^2=\psi_2^2\quad\text{or}\quad\psi_1^2x_0=\psi_2^2. &&\text{zero-product rule}
\end{align}

\textbf{Final Result.}
\[
\boxed{F_\Phi=-16\frac{(\psi_1^2x_0^2-\psi_2^2)(\psi_1^2x_0-\psi_2^2)}{x_0(x_0-1)^2},
\qquad
F_\Phi=0\Longleftrightarrow
\psi_1^2x_0^2=\psi_2^2\ \text{or}\ \psi_1^2x_0=\psi_2^2}
\]
\hfill$\blacksquare$

core_reasoning_5:
\textbf{Claim.}
For weakly coupled \(SU(N)\), \(N=4\) super Yang--Mills on \(M_3\times S^1\), the vacuum energy is zero when scalars, vectors, and fermions are all anti-periodic:
\[
\langle E_{\mathrm{SYM}}\rangle=0.
\]
If the six scalars and gauge vector are periodic while the fermions are anti-periodic, then
\[
\langle E_{\mathrm{SYM}*}\rangle=-\frac{\pi^2V_2}{6\delta^3}(N^2-1),
\qquad
E_0=\frac34\langle E_{\mathrm{SYM}*}\rangle\quad(N\to\infty).
\]

\textbf{Premises.}
\[
\begin{aligned}
\text{(P1)}\quad &\langle E_{\mathrm{scalar}}\rangle=-\frac{\pi^2V_2}{6\delta^3}X.\\
\text{(P2)}\quad &X_{\mathrm{even}}=\sum_{n=1}^{\infty}(2n)^3=\frac{8}{120},
\qquad
X_{\mathrm{odd}}=\sum_{n=1}^{\infty}(2n-1)^3=-\frac{7}{120}.\\
\text{(P3)}\quad &\text{The adjoint multiplicity is }N^2-1.\\
\text{(P4)}\quad &\text{The field-content weights are }6\text{ scalar }+2\text{ vector }-8\text{ fermion for common anti-periodicity}.\\
\text{(P5)}\quad &\text{For periodic bosons and anti-periodic fermions, the weighted factor is }6+2+8\cdot\frac78.\\
\text{(P6)}\quad &E_0=-\frac{L^3\pi^4}{2\kappa\delta^3}V_2,
\qquad \frac{L^3}{\kappa}=\frac{N^2}{4\pi^2}.\\
\text{(P7)}\quad &V_2>0,
\qquad \delta>0.
\end{aligned}
\]

\textbf{Derivation.}
For common anti-periodic boundary conditions,
\begin{align}
\langle E_{\mathrm{SYM}}\rangle
&=-\frac{\pi^2V_2}{6\delta^3}X_{\mathrm{odd}}(N^2-1)(6+2-8) &&\text{by (P1)--(P4)}\\
&=-\frac{\pi^2V_2}{6\delta^3}\left(-\frac{7}{120}\right)(N^2-1)\cdot0 &&\text{by (P2)}\\
&=0. \label{eq:all-anti}
\end{align}
For periodic bosons and anti-periodic fermions,
\begin{align}
6+2+8\cdot\frac78
&=8+7 &&\text{arithmetic}\\
&=15. \label{eq:factor15}
\end{align}
Thus
\begin{align}
\langle E_{\mathrm{SYM}*}\rangle
&=-\frac{\pi^2V_2}{6\delta^3}X_{\mathrm{even}}(N^2-1)\left(6+2+8\cdot\frac78\right) &&\text{by (P1), (P3), (P5)}\\
&=-\frac{\pi^2V_2}{6\delta^3}\left(\frac{8}{120}\right)(N^2-1)(15) &&\text{by (P2) and \eqref{eq:factor15}}\\
&=-\frac{\pi^2V_2}{6\delta^3}(N^2-1). \label{eq:symstar}
\end{align}
For the gravitational AdS-soliton energy,
\begin{align}
E_0
&=-\frac{L^3\pi^4}{2\kappa\delta^3}V_2 &&\text{by (P6)}\\
&=-\frac{\pi^4V_2}{2\delta^3}\left(\frac{N^2}{4\pi^2}\right) &&\text{by (P6)}\\
&=-\frac{\pi^2V_2}{8\delta^3}N^2. \label{eq:e0-largeN}
\end{align}
At large \(N\), \(N^2-1=N^2+O(1)\), so
\begin{align}
\frac{E_0}{\langle E_{\mathrm{SYM}*}\rangle}
&=\frac{-\pi^2V_2N^2/(8\delta^3)}{-\pi^2V_2(N^2-1)/(6\delta^3)} &&\text{by \eqref{eq:symstar} and \eqref{eq:e0-largeN}}\\
&=\frac{6}{8}\frac{N^2}{N^2-1} &&\text{cancel common factors}\\
&\longrightarrow \frac34 &&\text{as }N\to\infty.
\end{align}

\textbf{Final Result.}
\[
\boxed{\langle E_{\mathrm{SYM}}\rangle=0,
\qquad
\langle E_{\mathrm{SYM}*}\rangle=-\frac{\pi^2V_2}{6\delta^3}(N^2-1),
\qquad
E_0=\frac34\langle E_{\mathrm{SYM}*}\rangle\ (N\to\infty)}
\]
\hfill$\blacksquare$

core_reasoning_7:
\textbf{Claim.}
The ten-dimensional type-IIB supersymmetry condition includes both charge signs:
\[
|q_1|=|q_2|
\Longrightarrow
(q_1=q_2)\ \text{or}\ (q_1=-q_2).
\]
Thus the uplift admits the \(q_1=q_2\) supersymmetric case in addition to the five-dimensional branch \(q_1=-q_2\).

\textbf{Premises.}
\[
\begin{aligned}
\text{(P1)}\quad &q_1,q_2\in\mathbb{R}.\\
\text{(P2)}\quad &\text{The ten-dimensional integrability determinants vanish when }|q_1|=|q_2|.\\
\text{(P3)}\quad &\text{Vanishing of the ten-dimensional integrability determinants ensures a solution of the}\nonumber\\
&\text{type-IIB Killing spinor equation }D\epsilon=0.\\
\text{(P4)}\quad &\text{The five-dimensional Killing spinors were explicitly integrated for }q_1=-q_2.\\
\text{(P5)}\quad &a,b\in\mathbb{R}\Longrightarrow |a|=|b|\Longleftrightarrow a^2=b^2.\\
\text{(P6)}\quad &a^2-b^2=(a-b)(a+b).
\end{aligned}
\]

\textbf{Derivation.}
Assume the ten-dimensional supersymmetry condition holds:
\begin{align}
|q_1|&=|q_2| &&\text{IIB condition in (P2)}\\
q_1^2&=q_2^2 &&\text{by (P1) and (P5)}\\
q_1^2-q_2^2&=0 &&\text{subtract }q_2^2\\
(q_1-q_2)(q_1+q_2)&=0 &&\text{by (P6)}.
\end{align}
By the zero-product rule,
\begin{align}
(q_1-q_2)(q_1+q_2)=0
&\Longrightarrow q_1-q_2=0\quad\text{or}\quad q_1+q_2=0\\
&\Longrightarrow q_1=q_2\quad\text{or}\quad q_1=-q_2. \label{eq:two-signs}
\end{align}
For either sign in \eqref{eq:two-signs}, the premise \(|q_1|=|q_2|\) holds, so
\begin{align}
q_1=q_2\ \text{or}\ q_1=-q_2
&\Longrightarrow |q_1|=|q_2| &&\text{by (P1) and (P5)}\\
&\Longrightarrow \text{ten-dimensional integrability determinants vanish} &&\text{by (P2)}\\
&\Longrightarrow \exists\,\epsilon\neq0\text{ such that }D\epsilon=0 &&\text{by (P3)}.
\end{align}
Since the five-dimensional construction explicitly covers \(q_1=-q_2\),
\begin{align}
q_1=q_2
&\text{ is the additional ten-dimensional sign branch} &&\text{by (P4) and \eqref{eq:two-signs}}.
\end{align}

\textbf{Final Result.}
\[
\boxed{|q_1|=|q_2|\Longrightarrow
\bigl(q_1=q_2\ \text{or}\ q_1=-q_2\bigr),
\quad\text{so the IIB uplift includes }q_1=q_2\text{ in addition to the }D=5\text{ branch }q_1=-q_2}
\]
\hfill$\blacksquare$
